#!/usr/bin/env node
// Generated by Agent Team Kit 0.21.0. Do not edit.
// with-lock.sh without bash: run a command inside a hardware pool with a fixed number of slots, so parallel threads
// share one machine. Same arguments, same lock folders and the same exit codes as with-lock.sh, so the two can be mixed
// on one machine (a slot taken by one is seen by the other).
//
//   node scripts/agent-team/with-lock.mjs build -- npm run build
//
// Pools come from AGENT_TEAM_POOLS ("name:slots name:slots ..."): the environment, then .agent-team/gates.json
// "pools", then AGENT_TEAM_POOLS in .agent-team/config.sh, then the kit's defaults. Slots are folders under
// ~/.agent-team/<project>/locks/<pool>/slot-<n> holding the owner's pid; a slot whose owner is gone is reclaimed.
// Waits up to WITH_LOCK_TIMEOUT seconds (default 1200, polling every WITH_LOCK_POLL, default 15), then exits 75 so
// the thread can send BLOCKED instead of hanging. A bad pool or usage exits 64.
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { context, shellVars } from './report.mjs';

export const DEFAULT_POOLS = 'build:2 browser:3 emulator:2 simulator:2 backend:1';
export const EX_USAGE = 64;
export const EX_TEMPFAIL = 75;

const readJson = (f) => { try { return JSON.parse(readFileSync(f, 'utf8')); } catch { return undefined; } };
const readVars = (f) => (existsSync(f) ? shellVars(readFileSync(f, 'utf8')) : {});

/** What lib.sh's at_init and with-lock.sh work out: pools, the lock folder, the timeout and the poll interval. */
export function lockSettings(env = process.env, cwd = process.cwd()) {
  const ctx = context(env, cwd);
  const config = readVars(env.AGENT_TEAM_CONFIG || join(ctx.root, '.agent-team/config.sh'));
  const gates = readJson(join(ctx.root, '.agent-team/gates.json'));
  const fromGates = gates?.pools && Object.keys(gates.pools).length ? Object.entries(gates.pools).map(([k, v]) => `${k}:${v}`).join(' ') : '';
  const num = (v, d) => (/^\d+$/.test(String(v ?? '')) ? Number(v) : d);
  return {
    ctx,
    pools: env.AGENT_TEAM_POOLS || fromGates || config.AGENT_TEAM_POOLS || DEFAULT_POOLS,
    lockRoot: env.AGENT_TEAM_LOCK_ROOT || join(ctx.home, 'locks'),
    timeout: num(env.WITH_LOCK_TIMEOUT, 1200),
    poll: num(env.WITH_LOCK_POLL, 15),
  };
}

/** The slot count of a pool in a "name:slots ..." list, or 0 when the pool is unknown. */
export function poolSlots(pools, pool) {
  let slots = '';
  for (const entry of String(pools).split(/\s+/).filter(Boolean)) if (entry.split(':')[0] === pool) slots = entry.slice(entry.indexOf(':') + 1);
  return /^\d+$/.test(slots) && Number(slots) >= 1 ? Number(slots) : 0;
}

const alive = (pid) => {
  if (!/^\d+$/.test(pid)) return false;
  try { process.kill(Number(pid), 0); return true; } catch (e) { return e.code === 'EPERM'; }
};

/** Takes a free slot of the pool folder, or reclaims one whose owner died: the slot's path, or null when all are busy. */
export function claim(dir, slots, pid = process.pid) {
  mkdirSync(dir, { recursive: true });
  const take = (slot) => { try { mkdirSync(slot); } catch { return false; } writeFileSync(join(slot, 'pid'), `${pid}\n`); return true; };
  for (let i = 1; i <= slots; i++) {
    const slot = join(dir, `slot-${i}`);
    if (take(slot)) return slot;
    const pidFile = join(slot, 'pid');
    if (existsSync(pidFile) && !alive(readFileSync(pidFile, 'utf8').trim())) {
      rmSync(slot, { recursive: true, force: true });
      if (take(slot)) return slot;
    }
  }
  return null;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Waits for a slot of `pool`: { slot, release } once one is free, { code: 75 } after the timeout, { code: 64 } for an
 * unknown pool. `log` gets the lines with-lock.sh writes to stderr.
 */
export async function acquire(pool, settings = lockSettings(), log = (s) => process.stderr.write(s)) {
  const slots = poolSlots(settings.pools, pool);
  if (!slots) { log(`with-lock: unknown pool '${pool}' (pools: ${settings.pools})\n`); return { code: EX_USAGE }; }
  const dir = join(settings.lockRoot, pool);
  const start = Date.now();
  let slot;
  while (!(slot = claim(dir, slots))) {
    if (Date.now() - start >= settings.timeout * 1000) { log(`with-lock: no free '${pool}' slot after ${settings.timeout}s (BLOCKED)\n`); return { code: EX_TEMPFAIL }; }
    await sleep(settings.poll * 1000);
  }
  let released = false;
  const release = () => { if (!released) { released = true; rmSync(slot, { recursive: true, force: true }); } };
  return { slot, release };
}

/** Runs a command and resolves with its exit code (128 + the signal number when a signal ended it, as a shell reports). */
export function runCommand(cmd, args, opts = {}) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32', ...opts });
    child.on('error', (e) => { process.stderr.write(`with-lock: ${cmd}: ${e.message}\n`); resolve(e.code === 'ENOENT' ? 127 : 126); });
    child.on('exit', (code, signal) => resolve(code ?? 128 + ({ SIGHUP: 1, SIGINT: 2, SIGTERM: 15, SIGKILL: 9 }[signal] ?? 1)));
  });
}

export async function main(argv, env = process.env) {
  const [pool, sep, cmd, ...args] = argv;
  const settings = lockSettings(env);
  if (!pool || sep !== '--' || !cmd) { process.stderr.write(`usage: with-lock.mjs <pool> -- <command...>  (pools: ${settings.pools})\n`); return EX_USAGE; }
  const got = await acquire(pool, settings);
  if (!got.slot) return got.code;
  // Give the slot back however this process ends.
  process.on('exit', got.release);
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(sig, () => { got.release(); process.exit(128 + ({ SIGHUP: 1, SIGINT: 2, SIGTERM: 15 }[sig])); });
  process.stderr.write(`with-lock: ${pool} ${basename(got.slot)} -> ${[cmd, ...args].join(' ')}\n`);
  const code = await runCommand(cmd, args);
  got.release();
  return code;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).then((code) => { process.exitCode = code; });
}
